	StringBuilder onXFormatErrorBuilder = new StringBuilder();
	if (compilerVersion < 8) {
		onXFormatErrorBuilder.append("The correct format up to JDK7 is ");
		onXFormatErrorBuilder.append(errorName);
		onXFormatErrorBuilder.append("=@__({@SomeAnnotation, @SomeOtherAnnotation}))");
	} else {
		onXFormatErrorBuilder.append("The correct format for JDK8+ is ");
		onXFormatErrorBuilder.append(errorName);
		onXFormatErrorBuilder.append("_={@SomeAnnotation, @SomeOtherAnnotation})");
	}
	String onXFormatError = onXFormatErrorBuilder.toString();

	List<JCExpression> rawArgs = ast.args;
	int argCount = rawArgs.size();
