	for (int argIdx = 0; argIdx < argCount; argIdx++) {
		JCExpression param = rawArgs.get(argIdx);
		boolean allowRaw = false;
		String nameOfParam = "value";
		JCExpression valueOfParam = null;
		if (param instanceof JCAssign) {
			JCAssign assign = (JCAssign) param;
			JCExpression assignedName = assign.lhs;
			if (assignedName instanceof JCIdent) {
				JCIdent ident = (JCIdent) assignedName;
				nameOfParam = ident.name.toString();
			}
			valueOfParam = assign.rhs;
		}

		int nameLength = nameOfParam.length();
		int lastIdx = nameLength;
		while (lastIdx > 0) {
			char trailingChar = nameOfParam.charAt(lastIdx - 1);
			if (trailingChar != '_') {
				break;
			}
			lastIdx--;
		}
		allowRaw = lastIdx < nameLength;
		nameOfParam = nameOfParam.substring(0, lastIdx);

		if (!parameterName.equals(nameOfParam)) {
			params.append(param);
			continue outer;
		}

		JCTree topTree = annotationNode.top().get();
		JCCompilationUnit compilationUnit = (JCCompilationUnit) topTree;
		DiagnosticPosition diagnosticPosition = param.pos();
		int startPos = param.pos;
		int endPos = Javac.getEndPosition(diagnosticPosition, compilationUnit);
		Context javacContext = annotationNode.getContext();
		CompilerMessageSuppressor messageSuppressor = new CompilerMessageSuppressor(javacContext);
		messageSuppressor.removeAllBetween(compilationUnit.sourcefile, startPos, endPos);

		if (valueOfParam instanceof JCAnnotation) {
			JCAnnotation boxedAnnotation = (JCAnnotation) valueOfParam;
			JCTree annotationTypeTree = boxedAnnotation.annotationType;
			String dummyAnnotationName = annotationTypeTree.toString();
			StringBuilder dummyNameBuilder = new StringBuilder(dummyAnnotationName.length());
			int dummyLength = dummyAnnotationName.length();
			for (int dummyIdx = 0; dummyIdx < dummyLength; dummyIdx++) {
				char dummyChar = dummyAnnotationName.charAt(dummyIdx);
				if (dummyChar != '_' && dummyChar != '$' && dummyChar != 'x' && dummyChar != 'X') {
					dummyNameBuilder.append(dummyChar);
				}
			}
			dummyAnnotationName = dummyNameBuilder.toString();
			if (dummyAnnotationName.length() > 0) {
				if (allowRaw) {
					result.append(boxedAnnotation);
				} else {
					annotationNode.addError(onXFormatError);
				}
				continue outer;
			}
			List<JCExpression> boxedArgs = boxedAnnotation.args;
			int boxedArgCount = boxedArgs.size();
			for (int boxedArgIdx = 0; boxedArgIdx < boxedArgCount; boxedArgIdx++) {
				JCExpression expr = boxedArgs.get(boxedArgIdx);
				JCExpression unboxedExpr = expr;
				if (expr instanceof JCAssign && ((JCAssign) expr).lhs instanceof JCIdent) {
					JCAssign innerAssign = (JCAssign) expr;
					JCIdent id = (JCIdent) innerAssign.lhs;
					String innerName = id.name.toString();
					if ("value".equals(innerName)) {
						unboxedExpr = innerAssign.rhs;
					} else {
						addError(errorName, annotationNode);
					}
				}

				if (unboxedExpr instanceof JCAnnotation) {
					result.append((JCAnnotation) unboxedExpr);
				} else if (unboxedExpr instanceof JCNewArray) {
					JCNewArray nestedArray = (JCNewArray) unboxedExpr;
					List<JCExpression> nestedElems = nestedArray.elems;
					int nestedCount = nestedElems.size();
					for (int nestedIdx = 0; nestedIdx < nestedCount; nestedIdx++) {
						JCExpression nestedElem = nestedElems.get(nestedIdx);
						if (nestedElem instanceof JCAnnotation) {
							result.append((JCAnnotation) nestedElem);
						} else {
							addError(errorName, annotationNode);
							continue outer;
						}
					}
				} else {
					annotationNode.addError(onXFormatError);
					continue outer;
				}
			}
		} else if (valueOfParam instanceof JCNewArray) {
			JCNewArray arr = (JCNewArray) valueOfParam;
			List<JCExpression> arrayElems = arr.elems;
			if (arrayElems.isEmpty()) {
				// Just remove it, this is always fine.
			} else if (allowRaw) {
				int arrayCount = arrayElems.size();
				for (int arrayIdx = 0; arrayIdx < arrayCount; arrayIdx++) {
					JCExpression arrayElem = arrayElems.get(arrayIdx);
					if (arrayElem instanceof JCAnnotation) {
						result.append((JCAnnotation) arrayElem);
					} else {
						annotationNode.addError(onXFormatError);
					}
				}
			} else {
				annotationNode.addError(onXFormatError);
			}
		} else {
			annotationNode.addError(onXFormatError);
		}
	}

	for (JCAnnotation annotation : result) {
		clearTypes(annotation);
	}
	ast.args = params.toList();
	return result.toList();
}

